                { id: 'cono_sur', name: 'Cono Sur', size: 11000, growth: 0.03, entryFee: 3000, regPressure: 0.7, esgPressure: 0.7 },
                { id: 'mercado_norte', name: 'Mercado del Norte', size: 38000, growth: 0.04, entryFee: 5000, regPressure: 0.8, esgPressure: 0.9 },
                { id: 'europa_occidental', name: 'Europa Occidental', size: 28000, growth: 0.02, entryFee: 6000, regPressure: 0.95, esgPressure: 0.95 },
                { id: 'europa_central', name: 'Europa Central', size: 19000, growth: 0.05, entryFee: 4000, regPressure: 0.8, esgPressure: 0.7 },
