                { id: 'asia_sudeste', name: 'Asia Sudeste', size: 31000, growth: 0.08, entryFee: 4500, regPressure: 0.3, esgPressure: 0.3 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000,
                    esgRating: 45,
                    carbonIntensity: 100,
                    activeMarkets: ['mercado_central', 'region_andina'],
                    marketShares: { mercado_central: 20, region_andina: 12 },
                    profitHistory: [],
                    esgHistory: [],
                    revenueHistory: [],
                    carbonHistory: [],
                    lastEvent: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sustainabilityPct: 3,
                    pricingStrategy: 'balanced',
                    productionMode: 'standard',
                    expandMarket: 'none'
                };
            }
            this._updateMarketOptions(state);
            this._updateEventPanel(state);
            this._syncControlsFromDecisions(state);
            this._applyEndState(state);
        }

        validateDecisions(decisions) {
            var sustainInput = document.getElementById('sustainInput');
            if (sustainInput) decisions.sustainabilityPct = parseFloat(sustainInput.value) || 0;

            var pricingSelect = document.getElementById('pricingSelect');
            if (pricingSelect) decisions.pricingStrategy = pricingSelect.value;

            var productionSelect = document.getElementById('productionSelect');
            if (productionSelect) decisions.productionMode = productionSelect.value;

            var expandSelect = document.getElementById('expandSelect');
            if (expandSelect) decisions.expandMarket = expandSelect.value;

            if (decisions.sustainabilityPct < 0 || decisions.sustainabilityPct > 15) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('sustain_warning'), 'warning'
                );
                return false;
            }

            if (decisions.expandMarket !== 'none') {
                var ds = window.mySimulation.state.domainState;
                var market = this._findMarket(decisions.expandMarket);
                if (market && ds.cash < market.entryFee) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('cash_warning'), 'warning'
                    );
                    return false;
                }
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var self = this;
            var period = state.currentPeriod;

            // 1. Revenue from active markets
            var totalRevenue = 0;
            var marketRevenues = {};

            ds.activeMarkets.forEach(function(mId) {
                var m = self._findMarket(mId);
                if (!m) return;
                var share = ds.marketShares[mId] || 0;
                var quarterRev = (m.size / 4) * (share / 100);

                // Organic share growth influenced by pricing and ESG fit
                var growthMod = 0.3;
                if (d.pricingStrategy === 'mass') growthMod = 0.5;
                if (d.pricingStrategy === 'premium') growthMod = 0.15;
                if (ds.esgRating > 60 && m.esgPressure > 0.6) growthMod += 0.2;
                ds.marketShares[mId] = Math.min(share + growthMod + 0.15, 35);

                // Apply market natural growth
                quarterRev *= (1 + m.growth / 4);

                marketRevenues[mId] = quarterRev;
                totalRevenue += quarterRev;
            });

            // 2. Pricing modifier
            var volumeMod = 1.0;
            var marginRate = 0.32;
            if (d.pricingStrategy === 'mass') { volumeMod = 1.15; marginRate = 0.24; }
            if (d.pricingStrategy === 'premium') { volumeMod = 0.82; marginRate = 0.42; }
            totalRevenue = totalRevenue * volumeMod;

            // 3. Production cost
            var prodCostMod = 1.0;
            if (d.productionMode === 'hybrid') prodCostMod = 1.10;
            if (d.productionMode === 'green') prodCostMod = 1.20;

            var baseCogs = totalRevenue * (1 - marginRate);
            var actualCogs = baseCogs * prodCostMod;
            var grossProfit = totalRevenue - actualCogs;

            // 4. Sustainability cost
            var sustainCost = totalRevenue * (d.sustainabilityPct / 100);

            // 5. Market expansion
            var entryCost = 0;
            var expandedName = '';
            if (d.expandMarket !== 'none') {
                var newMarket = this._findMarket(d.expandMarket);
                if (newMarket && ds.activeMarkets.indexOf(d.expandMarket) === -1) {
                    entryCost = newMarket.entryFee;
                    ds.activeMarkets.push(d.expandMarket);
                    ds.marketShares[d.expandMarket] = 3;
                    expandedName = newMarket.name;
                }
            }

            // 6. Geopolitical event effects
            var eventCost = 0;
            var eventMsg = '';

            if (period === 4) {
                if (ds.activeMarkets.indexOf('mercado_norte') !== -1) {
                    var tariffHit = (marketRevenues['mercado_norte'] || 0) * volumeMod * 0.18;
                    eventCost += tariffHit;
                    eventMsg = window.mySimulation.t('event_tariff_active');
                } else {
                    eventMsg = window.mySimulation.t('event_tariff_safe');
                }
            }

            if (period === 6) {
                var euActive = false;
                var euPenalty = 0;
                ['europa_occidental', 'europa_central'].forEach(function(eid) {
                    if (ds.activeMarkets.indexOf(eid) !== -1) {
                        euActive = true;
                        if (ds.carbonIntensity > 60) {
                            euPenalty += (marketRevenues[eid] || 0) * volumeMod * 0.15;
                        }
                    }
                });
                if (euActive && ds.carbonIntensity > 60) {
                    eventCost += euPenalty;
                    eventMsg = window.mySimulation.t('event_carbon_penalty');
                } else if (euActive) {
                    eventMsg = window.mySimulation.t('event_carbon_safe');
                } else {
                    eventMsg = window.mySimulation.t('event_carbon_safe');
                }
            }

            if (period === 8) {
                if (ds.esgRating < 60) {
                    eventCost += 2000;
                    ds.esgRating = Math.max(0, ds.esgRating - 8);
                    eventMsg = window.mySimulation.t('event_activist_penalty');
                } else {
                    ds.esgRating = Math.min(100, ds.esgRating + 3);
                    eventMsg = window.mySimulation.t('event_activist_safe');
                }
            }

            if (period === 10) {
                if (ds.activeMarkets.indexOf('asia_sudeste') !== -1) {
                    var geoHit = (marketRevenues['asia_sudeste'] || 0) * volumeMod * 0.30;
                    eventCost += geoHit;
                    eventMsg = window.mySimulation.t('event_geo_active');
                } else {
                    eventMsg = window.mySimulation.t('event_geo_safe');
                }
            }

            if (period === 12) {
                if (d.sustainabilityPct < 8) {
                    eventCost += totalRevenue * 0.12;
                    eventMsg = window.mySimulation.t('event_climate_penalty');
                } else {
                    eventMsg = window.mySimulation.t('event_climate_safe');
                }
            }

            // 7. Final profit
            var profit = grossProfit - sustainCost - entryCost - eventCost;

            // 8. Update ESG rating
            var esgChange = 0;
            esgChange += d.sustainabilityPct * 0.7;
            if (d.productionMode === 'green') esgChange += 3;
            if (d.productionMode === 'hybrid') esgChange += 1.5;
            if (d.productionMode === 'standard') esgChange -= 0.5;
            esgChange -= 0.8;
            if (d.pricingStrategy === 'premium') esgChange += 0.5;
            ds.esgRating = Math.max(0, Math.min(100, ds.esgRating + esgChange));

            // 9. Update carbon intensity
            var carbonChange = 0;
            if (d.productionMode === 'green') carbonChange = -7;
            if (d.productionMode === 'hybrid') carbonChange = -3.5;
