            ds.cash = Math.round(ds.cash + profit);

            // 11. Store event
            ds.lastEvent = eventMsg;

            // 12. Push histories
            ds.profitHistory.push(Math.round(profit));
            ds.esgHistory.push(Math.round(ds.esgRating * 10) / 10);
            ds.revenueHistory.push(Math.round(totalRevenue));
            ds.carbonHistory.push(ds.carbonIntensity);

            // platform score: same composite getPerformanceSummary derives from history, recomputed here from the domainState accumulators so it is available every round, then clamped to 0 to 100
            var runTotalProfit = ds.profitHistory.reduce(function(s, p) { return s + p; }, 0);
            var runFinScore = this._finScore(runTotalProfit);
            var runEsgScore = ds.esgHistory[ds.esgHistory.length - 1];
            var runCarbonScore = Math.max(0, 100 - ds.carbonHistory[ds.carbonHistory.length - 1]);
