                period: period,
                revenue: Math.round(totalRevenue),
                profit: Math.round(profit),
                sustainCost: Math.round(sustainCost),
                entryCost: entryCost,
                eventCost: Math.round(eventCost),
                esgRating: Math.round(ds.esgRating * 10) / 10,
                carbonIntensity: ds.carbonIntensity,
                activeMarkets: ds.activeMarkets.length,
                expandedMarket: expandedName,
                eventMessage: eventMsg,
                cash: ds.cash
            };
        }

