        _findMarket(id) {
            for (var i = 0; i < this.MARKETS.length; i++) {
                if (this.MARKETS[i].id === id) return this.MARKETS[i];
            }
            return null;
        }

        _getEsgGrade(rating) {
            if (rating >= 90) return 'AAA';
            if (rating >= 80) return 'AA';
            if (rating >= 70) return 'A';
            if (rating >= 60) return 'BBB+';
            if (rating >= 50) return 'BBB-';
            if (rating >= 40) return 'BB+';
            if (rating >= 30) return 'BB';
            if (rating >= 20) return 'B';
            return 'CCC';
        }

        _updateMarketOptions(state) {
            var select = document.getElementById('expandSelect');
            if (!select) return;
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var active = (state.domainState && state.domainState.activeMarkets) ? state.domainState.activeMarkets : [];
            var prev = select.value;
            select.innerHTML = '';

            var noneOpt = document.createElement('option');
            noneOpt.value = 'none';
            noneOpt.textContent = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t('expand_none') : 'No Expansion This Quarter';
            select.appendChild(noneOpt);

            this.MARKETS.forEach(function(m) {
                if (active.indexOf(m.id) === -1) {
                    var opt = document.createElement('option');
                    opt.value = m.id;
                    opt.textContent = m.name + ' ' + T('entry_suffix', { fee: '$' + m.entryFee.toLocaleString() + 'M' });
                    select.appendChild(opt);
                }
            });

            var keep = false;
            if (prev && select.options) {
                for (var i = 0; i < select.options.length; i++) {
                    if (select.options[i].value === prev) { keep = true; break; }
                }
            }
            select.value = keep ? prev : 'none';
        }

        _updateEventPanel(state) {
            var panel = document.getElementById('eventPanel');
            var textEl = document.getElementById('eventText');
            if (!panel || !textEl) return;

            if (state.domainState && state.domainState.lastEvent) {
                panel.style.display = 'block';
                textEl.textContent = state.domainState.lastEvent;
            } else {
                panel.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CapstoneGlobalAdapter(), {
            simulationType: 'capstone_global_esg',
            maxPeriods: 12,
            autoSaveInterval: 30000
        });
